CREATE TABLE IF NOT EXISTS outreach_batch (
  id UUID NOT NULL DEFAULT gen_random_uuid(),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  created_by UUID NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_by UUID NOT NULL,
  deleted_at TIMESTAMPTZ,
  deleted_by UUID,
  sender_app_user_id UUID NOT NULL,
  organisation_id UUID,
  sourcing_request_id UUID,
  job_requirement_id UUID,
  is_consultant_sender BOOL NOT NULL DEFAULT false,
  notification_channel_id UUID NOT NULL,
  outreach_template_id UUID NOT NULL,
  outreach_batch_status_id UUID NOT NULL,
  audience_filter JSONB,
  credits_per_recipient INT4 NOT NULL DEFAULT 1,
  credits_reserved INT4 NOT NULL DEFAULT 0,
  recipient_count INT4 NOT NULL DEFAULT 0,
  scheduled_at TIMESTAMPTZ,
  started_at TIMESTAMPTZ,
  completed_at TIMESTAMPTZ,
  CONSTRAINT pk_outreach_batch PRIMARY KEY (id),
  CONSTRAINT ck_outreach_batch_consultant_needs_request CHECK (NOT is_consultant_sender OR sourcing_request_id IS NOT NULL),
  CONSTRAINT ck_outreach_batch_credits_nonneg CHECK (credits_per_recipient >= 0 AND credits_reserved >= 0 AND recipient_count >= 0),
  CONSTRAINT ck_outreach_batch_completed_range CHECK (completed_at IS NULL OR started_at IS NOT NULL),
  CONSTRAINT fk_outreach_batch_sender_app_user_id FOREIGN KEY (sender_app_user_id) REFERENCES app_user (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_outreach_batch_organisation_id FOREIGN KEY (organisation_id) REFERENCES organisation (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_outreach_batch_sourcing_request_id FOREIGN KEY (sourcing_request_id) REFERENCES sourcing_request (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_outreach_batch_job_requirement_id FOREIGN KEY (job_requirement_id) REFERENCES job_requirement (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_outreach_batch_notification_channel_id FOREIGN KEY (notification_channel_id) REFERENCES notification_channel (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_outreach_batch_outreach_template_id FOREIGN KEY (outreach_template_id) REFERENCES outreach_template (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_outreach_batch_outreach_batch_status_id FOREIGN KEY (outreach_batch_status_id) REFERENCES outreach_batch_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_outreach_batch_sender_app_user_id_created_at (sender_app_user_id, created_at DESC) WHERE deleted_at IS NULL,
  INDEX idx_outreach_batch_organisation_id (organisation_id) WHERE organisation_id IS NOT NULL,
  INDEX idx_outreach_batch_sourcing_request_id (sourcing_request_id) WHERE sourcing_request_id IS NOT NULL,
  INDEX idx_outreach_batch_job_requirement_id (job_requirement_id) WHERE job_requirement_id IS NOT NULL,
  INDEX idx_outreach_batch_outreach_batch_status_id_scheduled_at (outreach_batch_status_id, scheduled_at) WHERE deleted_at IS NULL,
  INDEX idx_outreach_batch_outreach_template_id (outreach_template_id),
  INDEX idx_outreach_batch_notification_channel_id (notification_channel_id)
);
