  CONSTRAINT uq_outreach_recipient_outreach_batch_id_candidate_profile_id UNIQUE (outreach_batch_id, candidate_profile_id),
  CONSTRAINT ck_outreach_recipient_credits_nonneg CHECK (credits_charged >= 0),
  CONSTRAINT ck_outreach_recipient_sent_range CHECK (sent_at IS NULL OR sent_at >= queued_at),
  CONSTRAINT fk_outreach_recipient_outreach_batch_id FOREIGN KEY (outreach_batch_id) REFERENCES outreach_batch (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_outreach_recipient_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_outreach_recipient_outreach_delivery_status_id FOREIGN KEY (outreach_delivery_status_id) REFERENCES outreach_delivery_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_outreach_recipient_provider_message_ref (provider_message_ref) WHERE provider_message_ref IS NOT NULL,
  INDEX idx_outreach_recipient_candidate_profile_id_queued_at (candidate_profile_id, queued_at DESC),
  INDEX idx_outreach_recipient_outreach_delivery_status_id_queued_at (outreach_delivery_status_id, queued_at) USING HASH WITH (bucket_count = 16),
  INDEX idx_outreach_recipient_queued_at (queued_at) USING HASH WITH (bucket_count = 16)
);
