  CONSTRAINT fk_outreach_reply_reply_intent_id FOREIGN KEY (reply_intent_id) REFERENCES reply_intent (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  INDEX idx_outreach_reply_outreach_recipient_id_received_at (outreach_recipient_id, received_at),
  INDEX idx_outreach_reply_received_at (received_at) USING HASH WITH (bucket_count = 8),
  INDEX idx_outreach_reply_notification_channel_id (notification_channel_id),
  INDEX idx_outreach_reply_reply_intent_id (reply_intent_id)
) WITH (ttl_expiration_expression = '(received_at + INTERVAL ''180 days'')', ttl_job_cron = '@daily');
