  CONSTRAINT pk_sourcing_submission PRIMARY KEY (id),
  CONSTRAINT uq_sourcing_submission_id_sourcing_request_id UNIQUE (id, sourcing_request_id),
  CONSTRAINT ck_sourcing_submission_response_range CHECK (employer_responded_at IS NULL OR employer_responded_at >= submitted_at),
  CONSTRAINT fk_sourcing_submission_sourcing_request_id FOREIGN KEY (sourcing_request_id) REFERENCES sourcing_request (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sourcing_submission_sourcing_shortlist_item_id FOREIGN KEY (sourcing_shortlist_item_id) REFERENCES sourcing_shortlist_item (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sourcing_submission_candidate_profile_id FOREIGN KEY (candidate_profile_id) REFERENCES candidate_profile (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sourcing_submission_user_consent_id FOREIGN KEY (user_consent_id) REFERENCES user_consent (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sourcing_submission_submission_status_id FOREIGN KEY (submission_status_id) REFERENCES submission_status (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT fk_sourcing_submission_job_application_id FOREIGN KEY (job_application_id) REFERENCES job_application (id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  UNIQUE INDEX uq_sourcing_submission_sourcing_request_id_candidate_profile_id (sourcing_request_id, candidate_profile_id) WHERE deleted_at IS NULL,
  INDEX idx_sourcing_submission_candidate_profile_id (candidate_profile_id),
  INDEX idx_sourcing_submission_sourcing_shortlist_item_id (sourcing_shortlist_item_id),
  INDEX idx_sourcing_submission_user_consent_id (user_consent_id),
  INDEX idx_sourcing_submission_job_application_id (job_application_id) WHERE job_application_id IS NOT NULL,
  INDEX idx_sourcing_submission_submission_status_id_submitted_at (submission_status_id, submitted_at) WHERE deleted_at IS NULL
);
